#define ATTR_STRONG_PCT 130
#define ATTR_WEAK_PCT 80
static inline uint16_t attrEffPct(uint8_t atk, uint8_t def) {
  if (atk == AT_FREE || def == AT_FREE || atk >= ATTR_COUNT || def >= ATTR_COUNT) return 100;
  if ((atk == AT_VACCINE && def == AT_VIRUS) || (atk == AT_VIRUS && def == AT_DATA) ||
      (atk == AT_DATA && def == AT_VACCINE)) return ATTR_STRONG_PCT;
  if ((def == AT_VACCINE && atk == AT_VIRUS) || (def == AT_VIRUS && atk == AT_DATA) ||
      (def == AT_DATA && atk == AT_VACCINE)) return ATTR_WEAK_PCT;
  return 100;
}

